import { buildSchema, graphql } from "graphql";
const schema = buildSchema("type Book { title: String! } type Query { books: [Book!]! }");

const rootValue = { books: () => [{ title: "Moon Trip" }, { title: "Sun Trip" }] };
const result = await graphql({ schema, rootValue, source: "{ books { title } }", variableValues: {} });
console.log(JSON.stringify(result.data));
